return items.map((item) => {
  const body = item.json.body || item.json || {};
  const headers = item.json.headers || {};
  const authHeader = String(headers.authorization || headers.Authorization || '').trim();
  const expectedApiKey = String($env.OUTREACH_EVIDENCE_API_KEY || '').trim();
  const platformBaseUrl = String($env.PLATAFORMA_ADMIN_BASE_URL || $env.PLATFORM_ADMIN_BASE_URL || '').trim().replace(/\/$/, '');
  const requestedIdCandidato = String(body.idCandidato || body.id_candidato || '').trim();
  const idCandidato = String(body.idCandidato || body.id_candidato || '').trim();
  const taskId = String(body.taskId || body.tarefaId || body.tarefa_id || '').trim();
  const memberId = String(body.memberId || body.membroId || body.membro_id || '').trim();
  const phoneDigits = String(body.telefone || body.memberPhone || body.whatsapp || '').replace(/\D/g, '');
  const normalizedPhone = phoneDigits ? (phoneDigits.startsWith('55') ? phoneDigits : (phoneDigits.length >= 10 && phoneDigits.length <= 11 ? `55${phoneDigits}` : phoneDigits)) : '';
  const mensagem = String(body.mensagem || body.message || body.evidencia || '').trim();
  const quantidadeValidada = Number(body.quantidadeValidada || body.quantidade || 1);
  const errors = [];

  if (expectedApiKey && authHeader !== `Bearer ${expectedApiKey}`) errors.push('Authorization Bearer invalido para evidencia da Equipe de Divulgacao.');
  if (!platformBaseUrl) errors.push('PLATAFORMA_ADMIN_BASE_URL nao configurada no n8n.');
  if (!idCandidato) errors.push('idCandidato ausente.');
  if (!memberId && !normalizedPhone) errors.push('Informe membroId/memberId ou telefone do membro.');
  if (!Number.isFinite(quantidadeValidada) || quantidadeValidada <= 0) errors.push('Quantidade validada deve ser maior que zero.');

  const valido = errors.length === 0;
  return {
    json: {
      valido,
      autorizado: !expectedApiKey || authHeader === `Bearer ${expectedApiKey}`,
      statusCode: valido ? 200 : (errors.some((error) => error.includes('Authorization')) ? 401 : 400),
      errors,
      requestedIdCandidato,
      idCandidato,
      taskId,
      memberId: memberId || null,
      telefone: normalizedPhone || null,
      mensagem,
      quantidadeValidada: Math.trunc(quantidadeValidada),
      canal: String(body.canal || 'whatsapp').trim(),
      origem: String(body.origem || 'n8n-whatsapp-divulgacao').trim(),
      platformUrl: platformBaseUrl ? `${platformBaseUrl}/api/campanhas/${idCandidato}/divulgacao/evidencias` : '',
      raw: body
    }
  };
});

return items.map((item) => ({
  json: {
    status: 'ok',
    message: 'Evidencia da Equipe de Divulgacao registrada na plataforma.',
    resposta_plataforma: item.json
  }
}));
